import fs from 'node:fs';
const version = fs.readFileSync('VERSION', 'utf8').trim();
const changelog = fs.readFileSync('CHANGELOG.md', 'utf8');
const notes = fs.readFileSync('RELEASE-NOTES.txt', 'utf8');
if (!changelog.includes(`## v${version}`)) { console.error(`CHANGELOG 缺少 v${version} 段落`); process.exit(1); }
if (!notes.includes(`v${version}`)) { console.error(`RELEASE-NOTES 缺少 v${version}`); process.exit(1); }
console.log('check ok: v' + version);

